'use strict';
const $=s=>document.querySelector(s),math=SalesReportMath;let report=null,request=0;
const time=value=>new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function invalidate(){request++;report=null;$('#sales-report-paper').hidden=true;$('#sales-report-rows').replaceChildren();$('#sales-report-summary').replaceChildren();$('#sales-report-print').disabled=true;$('#sales-report-csv').disabled=true;$('#sales-report-load').disabled=false;}
function render(data){$('#sales-report-heading').replaceChildren(node('h2','کاشێر — ڕاپۆرتی فرۆشتنی کاڵاکان'),node('p',data.from+' → '+data.to+' · بە کاتی بەغدا'),node('p','کاتی ڕاپۆرت: '+time(data.generated_at)+' · '+data.count+' کاڵا · دراو: دیناری عێراقی'));const summary=$('#sales-report-summary');for(const [label,key] of [['ژمارەی پسوولەی فرۆشتن','receipt_count'],['ژمارەی گەڕاندنەوەکان','return_count'],['فرۆشتن پێش داشکاندن / دیناری عێراقی','gross'],['داشکاندنی فرۆشتن / دیناری عێراقی','discounts'],['فرۆشتن دوای داشکاندن / دیناری عێراقی','sold_total'],['بەهای گەڕێندراوە / دیناری عێراقی','returned_total'],['بەهای خاوێن / دیناری عێراقی','net_total']]){const group=node('div');group.append(node('dt',label),node('dd',math.money(data.summary[key])));summary.append(group);}data.rows.forEach((r,i)=>{const row=node('tr');for(const value of [i+1,r.name,r.barcode||'—',math.quantity(r.sold_units),math.quantity(r.returned_units),math.quantity(r.net_units),math.money(r.sold_total),math.money(r.returned_total),math.money(r.net_total),math.money(r.receipt_count),time(r.last_activity_at)])row.append(node('td',String(value)));$('#sales-report-rows').append(row);});$('#sales-report-empty').hidden=data.rows.length!==0;$('#sales-report-paper').hidden=false;}
async function load(){invalidate();const mine=++request,from=$('#sales-report-from').value,to=$('#sales-report-to').value;if(!KashierData.loggedIn()){location.replace('auth.html?next=sales-report.html');return;}try{PurchaseReportMath.range(from,to);}catch(error){$('#sales-report-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);return;}$('#sales-report-load').disabled=true;$('#sales-report-status').textContent='خوێندنەوەی ڕاپۆرت…';try{const data=await KashierData.getSalesProductReport(from,to);if(mine!==request)return;math.validate(data,from,to);render(data);report=data;$('#sales-report-print').disabled=false;$('#sales-report-csv').disabled=false;$('#sales-report-status').textContent='ڕاپۆرتەکە ئامادەیە؛ بۆ مامەڵە نوێکان دووبارە ڕاپۆرت بخوێنەرەوە.';}catch(error){if(mine===request){invalidate();$('#sales-report-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);}}finally{if(mine===request)$('#sales-report-load').disabled=false;}}
$('#sales-report-form').addEventListener('submit',event=>{event.preventDefault();load();});for(const selector of ['#sales-report-from','#sales-report-to'])$(selector).addEventListener('input',()=>{invalidate();$('#sales-report-status').textContent='بۆ ماوەی نوێ ڕاپۆرت بخوێنەرەوە.';});$('#sales-report-print').addEventListener('click',()=>{if(report)window.print();});$('#sales-report-csv').addEventListener('click',()=>{if(!report)return;const blob=new Blob([math.csv(report,StocktakeExport.cell)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=node('a');link.href=url;link.download='kashier-sales-'+report.from+'-'+report.to+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),part=type=>parts.find(p=>p.type===type).value,today=part('year')+'-'+part('month')+'-'+part('day');$('#sales-report-from').value=today.slice(0,8)+'01';$('#sales-report-to').value=today;load();
